.h2:    tst.b   $11cf.w
        bne.s   .anim
        tst.b   $11ce.w
        beq.s   .out
        movem.l d0-d7/a0-a6,-(a7)
        moveq   #$36,d0
        moveq   #2,d1
        jsr     $7bb2.l
