; ---- first pass in a buffer: strip bitmap, sky over rows 16-64, shadows invalid ---------------------------------------------------
paint:  movea.l a5,a0
        lea     BAR.l,a1
        lea     2560(a0),a3
.b:     movem.l (a1)+,d0-d7
        movem.l d0-d7,(a0)
        lea     32(a0),a0
        cmpa.l  a3,a0
        blo.s   .b
