; ---- d0.w (0..65535) -> 5 decimal digit codes at (a1), leading zeros = blank (10) except the last -----------------------------------
conv5:  divu    #10000,d0
        move.b  d0,(a1)
        swap    d0
        andi.l  #$ffff,d0
        divu    #100,d0
        lea     BCD.l,a2
        move.w  d0,d2
        add.w   d2,d2
        move.w  (a2,d2.w),d3
        move.b  d3,2(a1)
        lsr.w   #8,d3
        move.b  d3,1(a1)
        swap    d0
        add.w   d0,d0
        move.w  (a2,d0.w),d3
        move.b  d3,4(a1)
        lsr.w   #8,d3
        move.b  d3,3(a1)
        moveq   #3,d2
        moveq   #10,d3
        movea.l a1,a2
.l:     tst.b   (a2)
        bne.s   .e
        move.b  d3,(a2)+
        dbra    d2,.l
.e:     rts

